Rules.InvariantScript:
Set(varOkS, IsMatch(txtStart.Text, "^([01]\d|2[0-3]):[0-5]\d$"));
Set(varOkE, IsMatch(txtEnd.Text, "^([01]\d|2[0-3]):[0-5]\d$"));
Set(varS, If(varOkS, Value(Left(txtStart.Text,2))*60 + Value(Right(txtStart.Text,2)), 0));
Set(varE, If(varOkE, Value(Left(txtEnd.Text,2))*60 + Value(Right(txtEnd.Text,2)), 0));
Set(varNow, Hour(Now())*60 + Minute(Now()));
Set(varBlocked, LookUp(colRooms, Id = ddroom.Selected.Id).Blocked);
Set(varHit, LookUp(colBookings, RoomId = ddroom.Selected.Id && varS < EndMin && varE > StartMin));
Set(varResult,
 If(!varOkS || !varOkE, {ok:false, msg:"Enter start and end time as HH:mm, for example 16:30."},
 varE <= varS, {ok:false, msg:"End time must be later than start time."},
 varE - varS > 120, {ok:false, msg:"Bookings cannot be longer than 2 hours (120 minutes)."},
 varS <= varNow, {ok:false, msg:"Start time must be after the current time."},
 varBlocked, {ok:false, msg:ddroom.Selected.Id & " is currently blocked and unavailable for booking."},
 !IsBlank(varHit), {ok:false, msg:"Overlaps an existing booking."},
 {ok:true, msg:"This time slot is open and meets all booking rules."}))
